// Obtiene los atributos de controles HTML conservando los valores visibles del formulario.
function atributosHtml(texto) {return Object.fromEntries([...texto.matchAll(/([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g)].map(par=>[par[1].toLowerCase(),decodificar(par[2]??par[3])]));}

// Lee las opciones y la selección del proveedor desde el HTML que MVC envía al navegador.
function opcionesProveedor(html) {const selector=[...html.matchAll(/<select\b([^>]*)>([\s\S]*?)<\/select>/gi)].find(par=>atributosHtml(par[1]).name==='ProveedorId');if(!selector)throw new Error('No se encontro el selector de proveedor.');return [...selector[2].matchAll(/<option\b([^>]*)>([\s\S]*?)<\/option>/gi)].map(par=>({valor:atributosHtml(par[1]).value??'',texto:decodificar(par[2]).trim(),seleccionado:/\bselected(?:\s|=|$)/i.test(par[1])}));}

// Comprueba las opciones obtenidas de API y la referencia seleccionada del producto.
function confirmarSelector(html,proveedores,seleccionado,caso) {const opciones=opcionesProveedor(html);confirmar(`${caso} conserva opciones API`,proveedores.every(proveedor=>opciones.some(opcion=>opcion.valor===proveedor.id&&opcion.texto===`${proveedor.razonSocial} (${proveedor.identificacion})`)));if(seleccionado)confirmar(`${caso} conserva proveedor seleccionado`,opciones.some(opcion=>opcion.valor===seleccionado&&opcion.seleccionado));}

// Verifica valores de producto y el campo que informa la causa del rechazo.
function confirmarFormularioProducto(html,formulario,campo,caso) {const controles=[...html.matchAll(/<input\b([^>]*)>/gi)].map(par=>atributosHtml(par[1]));for(const nombre of ['Codigo','Nombre','PrecioUnidadMedida','ExistenciaActual','ExistenciaMinima'])confirmar(`${caso} conserva ${nombre}`,controles.some(control=>control.name===nombre&&control.value===formulario[nombre]));const mensaje=[...html.matchAll(/<span\b([^>]*)>([\s\S]*?)<\/span>/gi)].find(par=>atributosHtml(par[1])['data-valmsg-for']===campo);confirmar(`${caso} informa error ${campo}`,!!mensaje&&/field-validation-error/.test(mensaje[1])&&decodificar(mensaje[2]).trim().length>0);}

